def find_continuous_ranges(nums):
    if not nums:
        return []
    res = []
    start = nums[0]
    for i in range(1, len(nums)):
        if nums[i] != nums[i-1] + 1:
            res.append([start, nums[i-1]])
            start = nums[i]
    res.append([start, nums[-1]])
    return res
